import subprocess, os, struct, fcntl, termios, select, time, pty
def run_pty(args, cwd, cols=80, rows=24):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    env=dict(os.environ)
    p = subprocess.Popen(["/workspace/executable"]+args, cwd=cwd, stdin=slave, stdout=slave, stderr=slave, close_fds=True, env=env)
    os.close(slave)
    out=b""
    end=time.time()+3
    while time.time()<end:
        r,_,_=select.select([master],[],[],0.5)
        if r:
            try:
                data=os.read(master, 4096)
                if not data: break
                out+=data
            except OSError: break
        else:
            if p.poll() is not None:
                try:
                    while True:
                        data=os.read(master,4096)
                        if not data: break
                        out+=data
                except: break
                break
    os.close(master)
    try: p.wait(timeout=2)
    except: p.kill()
    return out, p.returncode

out,rc=run_pty(["--no-color"], cwd="/tmp/gt/pagertest", cols=80, rows=24)
