struct ColorSection {
    matches: Vec<(String, Vec<String>)>,
    unknown: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct RepoConfig {
    model: String,
}

fn is_valid_terminal_color(s: &str) -> bool {
    match s {
        "black"|"red"|"green"|"yellow"|"blue"|"magenta"|"cyan"|"white"|
        "bright_black"|"bright_red"|"bright_green"|"bright_yellow"|"bright_blue"|"bright_magenta"|"bright_cyan"|"bright_white" => true,
        _ => {
            if s.is_empty() { return false; }
            if !s.chars().all(|c| c.is_ascii_digit()) { return false; }
            if let Ok(n) = s.parse::<u16>() {
                n <= 255
            } else { false }
        }
    }
}

fn terminal_color_code(s: &str) -> u8 {
    match s {
        "black" => 0,
        "red" => 1,
        "green" => 2,
        "yellow" => 3,
        "blue" => 4,
        "magenta" => 5,
        "cyan" => 6,
        "white" => 7,
        "bright_black" => 8,
        "bright_red" => 9,
        "bright_green" => 10,
        "bright_yellow" => 11,
        "bright_blue" => 12,
        "bright_magenta" => 13,
        "bright_cyan" => 14,
        "bright_white" => 15,
        _ => {
            // numeric
            s.parse::<u8>().unwrap_or(7)
        }
    }
}

