    author_tz_offset_secs: i32, // seconds east of UTC
    committer_name: String,
    committer_email: String,
    committer_ts: i64,
    committer_tz: String,
    committer_tz_offset_secs: i32,
    subject: String, // %s
    body: String,    // %b (with trailing newline? as git gives, e.g., "body\n" or "" if empty)
    raw_body: String, // %B (with trailing newline? e.g., "subject\n\nbody\n" or "subject\n")
    raw_message: String, // full message as stored (for medium/full presets, with blanks preserved)
}

fn parse_tz(tz_str: &str) -> i32 {
    // tz like +0000, -0800, +0530
    if tz_str.len() != 5 { return 0; }
    let sign = if tz_str.starts_with('-') { -1 } else { 1 };
    let hh: i32 = tz_str[1..3].parse().unwrap_or(0);
    let mm: i32 = tz_str[3..5].parse().unwrap_or(0);
    sign * (hh * 3600 + mm * 60)
}

