fn get_refs(repo_path: &str, include_remotes: bool) -> (Vec<BranchRef>, Option<String>, Option<String>) {
    // Returns (branches, head_branch_or_none_if_detached, head_commit)
    // Get all refs via for-each-ref
    let out = ProcCommand::new("git").args(["-C", repo_path, "for-each-ref", "--format=%(refname)%00%(objectname)%00%(*objectname)%00%(symref)"]).output().unwrap();
    let text = String::from_utf8_lossy(&out.stdout).to_string();
    let mut branches = Vec::new();
    for line in text.split('\n') {
        if line.is_empty() { continue; }
        let parts: Vec<&str> = line.split('\x00').collect();
        if parts.len() < 4 { continue; }
        let refname = parts[0];
        let obj = parts[1];
        let peeled = parts[2];
        let symref = parts[3];
        if refname.starts_with("refs/heads/") {
            let name = refname["refs/heads/".len()..].to_string();
            // Skip? No, include all locals
            // Commit is obj (should be commit)
            // Verify it's commit via cat-file? Assume commit (heads always point to commits)
            branches.push(BranchRef {
                name: name.clone(),
                display_name: name.clone(),
                commit: obj.to_string(),
                is_local: true,
                is_remote: false,
                is_tag: false,
                match_name_persistence: name.clone(),
            });
        } else if refname.starts_with("refs/remotes/") {
            if !include_remotes { continue; }
            // Exclude symrefs like origin/HEAD
            if !symref.is_empty() {
                continue;
            }
            let full = refname["refs/remotes/".len()..].to_string();
            // full like "origin/master", "fork/myfeat"
            // For origin/*, match name is short without origin/. For others, full?
            let match_name = if full.starts_with("origin/") {
                full["origin/".len()..].to_string()
            } else {
                full.clone()
            };
            branches.push(BranchRef {
                name: full.clone(),
                display_name: full.clone(),
                commit: obj.to_string(),
                is_local: false,
                is_remote: true,
                is_tag: false,
                match_name_persistence: match_name,
            });
        } else if refname.starts_with("refs/tags/") {
            let tag = refname["refs/tags/".len()..].to_string();
            let name = format!("tags/{}", tag);
            // Determine commit: if peeled non-empty, use peeled (annotated). Else if obj is commit, use obj. Else need to peel via rev-parse?
            let mut commit = String::new();
            if !peeled.is_empty() {
                commit = peeled.to_string();
            } else {
                // Check if obj is commit via cat-file -t?
                let t_out = ProcCommand::new("git").args(["-C", repo_path, "cat-file", "-t", obj]).output().unwrap();
                let t = String::from_utf8_lossy(&t_out.stdout).trim().to_string();
                if t == "commit" {
                    commit = obj.to_string();
                } else if t == "tag" {
                    // Annotated but peeled empty? Try rev-parse ^{commit}
                    let r_out = ProcCommand::new("git").args(["-C", repo_path, "rev-parse", &format!("{}^{{commit}}", refname)]).output();
                    if let Ok(ro) = r_out {
                        if ro.status.success() {
                            commit = String::from_utf8_lossy(&ro.stdout).trim().to_string();
                        } else {
                            continue; // skip non-commit tags
                        }
                    } else { continue; }
                } else {
                    continue;
                }
            }
            if commit.is_empty() { continue; }
            branches.push(BranchRef {
                name: name.clone(),
                display_name: tag.clone(), // for %d, show without tags/ prefix? Actually [v1.0] not [tags/v1.0]
                commit,
                is_local: false,
                is_remote: false,
                is_tag: true,
                match_name_persistence: name.clone(),
            });
        } else {
            // ignore others (stash, notes, etc.)
            continue;
        }
    }
    // Get HEAD
    let head_branch: Option<String>;
    let head_commit: Option<String>;
    // Try symbolic-ref
    let sym_out = ProcCommand::new("git").args(["-C", repo_path, "symbolic-ref", "-q", "HEAD"]).output().unwrap();
    if sym_out.status.success() {
        let sym = String::from_utf8_lossy(&sym_out.stdout).trim().to_string();
        // sym like refs/heads/master
        if sym.starts_with("refs/heads/") {
            head_branch = Some(sym["refs/heads/".len()..].to_string());
        } else {
            head_branch = Some(sym);
        }
        // Get commit via rev-parse HEAD
        let rev_out = ProcCommand::new("git").args(["-C", repo_path, "rev-parse", "HEAD"]).output().unwrap();
        if rev_out.status.success() {
            head_commit = Some(String::from_utf8_lossy(&rev_out.stdout).trim().to_string());
        } else {
            head_commit = None;
        }
    } else {
        // Detached
        head_branch = None;
        let rev_out = ProcCommand::new("git").args(["-C", repo_path, "rev-parse", "HEAD"]).output().unwrap();
        if rev_out.status.success() {
            head_commit = Some(String::from_utf8_lossy(&rev_out.stdout).trim().to_string());
        } else {
            head_commit = None;
        }
    }
    (branches, head_branch, head_commit)
}

