fn get_terminal_width() -> Option<usize> {
    // Use libc ioctl TIOCGWINSZ on stdout (fd 1)
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(1, libc::TIOCGWINSZ, &mut ws) == 0 {
            if ws.ws_col > 0 {
                return Some(ws.ws_col as usize);
            }
        }
        None
    }
}
