fn get_terminal_color_code(branch: &Branch, model: &LoadedModel) -> u8 {
    // Find matching pattern for terminal (first regex matching match_name_order_color), else unknown
    // match_name_order_color is for order/colors (stripped for origin/*, full for others, tags full, merges name as parsed)
