    let idx = branch.color_idx % model.terminal_unknown.len();
    terminal_color_code(&model.terminal_unknown[idx])
}

fn get_svg_color(branch: &Branch, model: &LoadedModel) -> String {
    let match_name = &branch.match_name_order_color;
